from src.memoize import memoize, fib_recursive, fib_memoized, fib_iterative


def test_fib_recursive():
    assert fib_recursive(0) == 0
    assert fib_recursive(1) == 1
    assert fib_recursive(10) == 55


def test_fib_memoized():
    assert fib_memoized(0) == 0
    assert fib_memoized(1) == 1
    assert fib_memoized(30) == 832040


def test_fib_iterative():
    assert fib_iterative(0) == 0
    assert fib_iterative(1) == 1
    assert fib_iterative(50) == 12586269025


def test_memoize_caches():
    call_count = [0]

    @memoize
    def expensive(n):
        call_count[0] += 1
        return n * n

    expensive(5)
    expensive(5)
    assert call_count[0] == 1


def test_memoize_different_args():
    @memoize
    def double(n):
        return n * 2

    assert double(3) == 6
    assert double(4) == 8
    assert double(3) == 6

